P3["LY-517"] = ("positive｜援例可成而遲滯：官鬼申金動而伏吟（化申金），丑月得土生相，成事在反覆拖延之後；妻財戌土動同主費耗先行。應期雙層：窗口為數月內，窗口內主座標申月（官逢值之月）。", "liuyao\n官鬼申金五爻動化申金伏吟，丑月土生金相、乙卯日木耗有限；妻財戌土上爻動化戌土同吟主費。世妻財未土初爻。四路：本氣＋（官相得生）／元忌鏈0／動化0（伏吟調速）／世應不計。動化方向：官化同支伏吟；反轉條件：未齊備。R61復推：申月逢值保留。", 0.57, T())
P3["LY-518"] = ("negative｜上書不利、宜止：父母巳火（文書）動化妻財子水回頭克，書章受克，且巳火申月死，化克無救。應期雙層：窗口為本月內，窗口內主座標巳日（父母逢值受克應驗之日）。", "liuyao\n父母巳火五爻動，申月火死、戊辰日土泄；化妻財子水回頭克（水克火），子水申月相克有力。世兄弟未土。四路：本氣−／元忌鏈−（化回頭克）／動化−／世應不計。動化方向：父化財回頭克；反轉條件：回頭克無解成立。R61復推：巳日保留。", 0.64, T())
P3["LY-519"] = ("positive｜功名可保：官鬼戌土動化妻財巳火，財回頭生官（火生土），官得化生為保全主象；子孫卯木動化官辰為牽連不改主線。應期雙層：窗口為本月內，窗口內主座標戌日（官逢值之日）。", "liuyao\n官鬼戌土上爻動，未月土旺、戊申日土扶；化妻財巳火，巳火生戌土為回頭生官。世父母申金五爻。子孫卯木初爻動化官辰土主另生牽連。四路：本氣＋／元忌鏈0／動化＋（官化財回頭生）／世應不計。動化方向：官化財回頭生；反轉條件：未齊備。表面方向（子化官主憂）經動化路推翻。R61復推：戌日逢值保留。", 0.6, T(cm=True, reason="初看子孫化官、軍糧被劫主功名憂，官動化財回頭生官，翻主斷為可保"))
P3["LY-520"] = ("negative｜收貨（囤貨）不利：妻財戌土持世，寅月土死木旺，兄弟寅木兩現旺克財，囤之先受劫耗。應期雙層：年／月檔，窗口內主座標戌月（財填實出脫之月，非得利之期）。囤貨對表：財休囚取出脫於生旺之時，戌月土旺為出脫窗。", "liuyao\n山雷頤靜卦同盤異日：寅月己亥日，妻財戌土世寅月死，兄弟寅木旺克財；子孫伏申無力生財。囤貨賣貨對表首選按財狀態：休囚取出脫於生旺之時。四路：本氣−／元忌鏈−（兄旺克財）／動化0／世應不計。動化方向：靜卦無動化；反轉條件：未齊備。R61復推：戌月出脫路保留。", 0.6, T())
P3["LY-521"] = ("positive｜往粵東探親帶貨可得利：妻財酉金持應得戊申日扶、申金財同旺，財兩現有氣；子孫辰土世生金，貨以金類（金屬器物之屬）為宜（傾向表述）。應期雙層：窗口為此行月內，窗口內主座標酉日（財逢值之日）。", "liuyao\n火山旅靜卦，妻財酉金四爻應未月休而戊申日金扶臨財申金三爻，財得日助；世子孫辰土生財。四路：本氣＋（財得日扶）／元忌鏈0／動化0／世應計（財應有氣＋）。動化方向：靜卦無動化；反轉條件：未齊備。R61復推：酉日逢值保留；貨種指針1條降為傾向。", 0.57, T())
P3["LY-522"] = ("negative｜買馬往南發賣不利：子孫丑土（畜／馬）動化官鬼子水回頭克（水？丑土克子水為本爻克化神，化神受制），且財路迂迴；妻財酉金雖旺，馬象受制主賣有損耗。應期雙層：窗口為本月內，窗口內主座標丑日（子孫逢值應驗之日）。", "liuyao\n子孫丑土初爻動，丑月土旺臨月有氣；化官鬼子水，子水丑月休，丑土克子水化神受制，畜化官主官方／損耗牽連。世官鬼亥水五爻。妻財酉金旺生子水為旁扶不改主象。四路：本氣0／元忌鏈−（化官牽連）／動化−／世應不計。動化方向：子化官、本爻克化神；反轉條件：未齊備。R61復推：丑日逢值保留。", 0.55, T())
P3["LY-523"] = ("positive｜兄病有救、可轉愈：子孫寅木（藥）持世動化卯木化進，又得甲寅日臨扶，藥神旺進克官；兄弟子水（兄用神）午月囚而得藥路，近段危、遠段向愈，終局單判向愈。應期雙層：窗口為本旬內，窗口內主座標卯日（藥神化神逢值之日）。", "liuyao\n代占兄病，用神兄弟子水上爻動化子孫卯木，子水午月囚、甲寅日木泄；子孫寅木二爻世動化卯木化進臨日，藥旺。官鬼戌土五爻應午月旺為病勢，近段重。四路：本氣−（兄囚）／元忌鏈＋（藥旺進克官）／動化＋（子化進）／世應不計。合參：路1−路2＋定有救遲成向。動化方向：子化進、兄化子；反轉條件：未齊備。應驗對象復述：病者為兄本人。病位鏈：官戌四／五爻土主脾胃區為旁證，指針不足不落死病位。R61復推：卯日保留。", 0.55, T())
P3["LY-524"] = ("positive｜子病可用附子（溫熱之劑方向可從，仍須醫者斟酌劑量）：子孫子水臨壬子日旺主寒象，官鬼巳火得未月相為溫藥之象，兄弟酉金動化父母戌土不礙藥路。應期雙層：窗口為數日內，窗口內主座標子日（子孫逢值、藥應之日）。", "liuyao\n父占子病用藥，以子孫子水初爻為子兼藥象，壬子日臨值旺，水寒之象顯；附子屬火，卦中官鬼巳火上爻未月相，溫制有象。兄弟酉金四爻動化父母戌土，酉金生子水為旁。四路：本氣＋（子臨日）／元忌鏈0／動化0／世應不計。動化方向：兄化父旁鏈；反轉條件：未齊備。應驗對象復述：病者為子本人。醫療類只作占斷參考。R61復推：子日保留。", 0.52, T())
P3["LY-525"] = ("positive｜父病可服牛黃丸（藥象可用）：子孫酉金持世得辛酉日臨值，子孫為藥旺而臨日，藥路有力。應期雙層：日檔近事，窗口為即日，主座標酉日（藥神臨值之日）。卡面月建記載不全（僅記亥日辛酉日），旺衰缺月建一環，置信下調。", "liuyao\n卡面殘損：asked_at月建不全，註明降置信。澤天夬靜卦，子孫酉金五爻世，辛酉日臨值；父母不上卦（父之用神伏藏，卡面未備伏飛細目），只以藥神子孫臨日定可服，不以父爻旺衰下愈否重斷。四路：本氣＋（藥臨日）／元忌鏈0／動化0／世應不計。動化方向：靜卦無動化；反轉條件：未齊備。應驗對象復述：服藥者為父本人。R61復推：酉日保留。", 0.45, T())
P3["LY-526"] = ("negative｜擇此日入宅有礙父母：父母未土兩現，子月土死水旺受泄，丁酉日金泄土，父母爻無氣，此日入宅於父母不利，宜改日。應期雙層：日檔，所擇之日即應，主座標該擇定日（卡面未給具體日期，只斷此日不宜）。", "liuyao\n澤地萃靜卦，父母未土上爻及初爻兩現，子月休囚死、丁酉日泄；官鬼巳火世生父母為薄扶不敵月死。四路：本氣−／元忌鏈0／動化0／世應不計。動化方向：靜卦無動化；反轉條件：未齊備。應驗對象復述：有礙落父母。R61復推：無具體日期座標，註明只斷日之宜忌。", 0.58, T())
P3["LY-527"] = ("negative｜家宅有礙、修補後功名短期仍不升：再占妻財卯木動化官鬼巳火、官巳動化父母未土，官化泄耗，修後官路仍滯；初占父母未土動化兄弟申金，宅象耗動。應期雙層：年檔，窗口內主座標巳年（官逢值之年方有轉機）。", "liuyao\n兩占合斷：初占大有父母未土五爻動化兄弟申金；再占歸妹妻財卯木二爻動化官鬼巳火、官鬼巳火初爻動化父母未土（火生土泄官）。酉月戊寅日，官巳酉月死。家宅指疑處（照壁大樹）以父母／木象旁指，不落死。功名對表無門類，按年檔逢值。四路：本氣−（官死化泄）／元忌鏈0／動化−／世應不計。動化方向：官化父泄；反轉條件：未齊備。R61復推：巳年逢值保留。", 0.55, T(di=True, reason="初占家宅、再占修補後功名兩占合斷，取舍以再占官象為功名主斷，存疑留痕"))
P3["LY-528"] = ("positive｜墳地形勢中吉可用：世兄弟申金得庚申日臨、丑月土生，來龍有氣；父母辰土、未土兩現得月旺，堂局有靠。無具體應期（形勢占），年檔不報單點。等級：中吉，不作大發斷（子孫亥水靜、官午休）。", "liuyao\n澤山咸靜卦，世兄弟申金三爻，丑月土生金相、庚申日臨值；父母未土應、辰土初，丑月土旺。子孫亥水、官鬼午火靜。四路：本氣＋（世臨日得月生）／元忌鏈0／動化0／世應計（應父母土生世＋）。動化方向：靜卦無動化；反轉條件：未齊備。形勢細目（水口道路）指針不足，只斷整體中吉，細目降為不報。R61：無應期斷語，復推不適用。", 0.56, T())
P3["LY-529"] = ("negative｜墳地形勢有缺、偏不宜：父母未土臨空（卡面註空亡午未），地象一處虛陷；父母戌土靜，世子孫子水無月日可考。置信下調：卡面未明記月日，旺衰缺月日兩環。應期不報（形勢占）。", "liuyao\n卡面殘損：原文未明記月日，僅註空亡午未，註明降置信。山地剝靜卦，父母未土初爻臨空，父母戌土四爻；妻財寅卯木、官鬼巳火應。四路：本氣0（無月日定旺衰）／元忌鏈0／動化0／世應不計。動化方向：靜卦無動化；反轉條件：未齊備。R61：無應期，復推不適用。", 0.4, T())
P3["LY-530"] = ("positive｜家宅人口大體平安、有小驚無大害：子孫申金持世動制官鬼寅木，福神制害；惟子孫化父母午火回頭克，主小驚反覆。置信下調：卡面未明記月日（僅註空亡子丑），旺衰缺月日。應期雙層：窗口為近月內，主座標申日（子孫逢值之日，傾向座標）。", "liuyao\n卡面殘損：月日未明記，註明降置信。水天需之乾：子孫申金四爻世動化父母午火回頭克；妻財子水上爻動化兄弟戌土，子水臨空（子丑空）動不為空。官鬼寅木二爻靜受申克。四路：本氣0／元忌鏈＋（子制官）／動化0（化克調量級）／世應不計。動化方向：子化父回頭克；反轉條件：未齊備。應驗對象：家宅人口整體。R61復推：申日傾向保留、粒度降檔註明。", 0.45, T())
P3["LY-531"] = ("positive｜僕人可歸：子孫酉金（僕以子孫／應下之象）持世靜，兄弟辰土動化丑土化退、兄弟未土動化戌土，歸路在動退之後。應期雙層：窗口為數日內，主座標酉日（子孫逢值之日）。置信下調：卡面未明記月日，旺衰缺月日。", "liuyao\n卡面殘損：月日未明記（註空亡午未），降置信。澤天夬之履：子孫酉金五爻世靜；兄弟未土上爻動化戌土、兄弟辰土三爻動化丑土化退。行人類對表：靜逢值取酉值。四路：本氣0／元忌鏈0／動化0／世應不計。動化方向：兄化退旁鏈；反轉條件：未齊備。應驗對象復述：歸者為僕人本人。R61復推：酉日保留。", 0.48, T())
P3["LY-532"] = ("negative｜自病重而反覆：六爻全動，世兄弟巳火動化官鬼子水回頭克，官鬼亥水應動臨空化兄弟午火，子孫多動主藥多方而效亂。近段亂、遠段官空待實仍壓，終局單判負向。置信下調：卡面未明記月日（註空亡戌亥）。應期雙層：窗口為近月內，主座標亥日（官空填實應期，傾向座標）。病位多爻亂動、三路衝突，不妄斷。", "liuyao\n卡面殘損：月日未明記，降置信。離之坎六爻全動：世兄巳上動化官子水回頭克世；官亥三應動臨空（戌亥空）化兄午火；子孫未、丑動化戌、辰；父母卯動化寅；財酉動化申。四路：本氣−（世化回頭克）／元忌鏈−／動化−／世應不計。動化方向：世化官回頭克；反轉條件：未齊備。應驗對象復述：病者本人。病位三路衝突按門檻不落。R61復推：亥日粒度降檔註明。", 0.42, T())
P3["LY-533"] = ("positive｜房價可索得而遲、得其大半：妻財午火持應臨空，官鬼辰土、戌土兩動化財巳火／兄弟亥水，經官動而化出財。應期雙層：窗口為近月內，主座標巳日（化財逢值之日）。置信下調：卡面未明記月日（註空亡午未）。", "liuyao\n卡面殘損：月日未明記，降置信。坎之坤：妻財午火三爻應臨空靜；官鬼辰土二爻動化妻財巳火，官鬼戌土五爻動化兄弟亥水。官動化財主索討經手而得價。四路：本氣0（財空待實）／元忌鏈0／動化＋（官化財）／世應計（財應空記0）。動化方向：官化財；反轉條件：未齊備。R61復推：巳日化財值保留。", 0.5, T())
P3["LY-534"] = ("negative｜具題不利：父母巳火（題本）動化妻財子水回頭克，文書受克，題本難准。置信下調：卡面未明記月日（註空亡戌亥）。應期雙層：窗口為近月內，主座標巳日（父母逢值受克應驗之日，傾向座標）。", "liuyao\n卡面殘損：月日未明記，降置信。風澤中孚之損：父母巳火五爻動化妻財子水回頭克（水克火）；世兄弟未土。四路：本氣−（化回頭克）／元忌鏈−／動化−／世應不計。動化方向：父化財回頭克；反轉條件：未齊備。R61復推：巳日保留、粒度註明傾向。", 0.52, T())
P3["LY-535"] = ("negative｜慮大計（考核）不利：官鬼不上卦（伏藏），妻財酉金應動化子孫丑土臨空，子孫辰土世動化父母卯木，考核之官象伏而不出，主留中／不利。置信下調：卡面未明記月日（註空亡子丑）。應期不報單點（官伏無出路）。", "liuyao\n卡面殘損：月日未明記，降置信。火山旅之明夷：官鬼不現於本卦（變卦亥水官為旁），兄弟巳火上動化財酉，財酉四應動化子丑空，子辰初世動化父卯。四路：本氣−（官伏）／元忌鏈0／動化−／世應不計。動化方向：財化子化空；反轉條件：伏官引撥未全，不翻。R61：無應期主座標註明。", 0.47, T())
